input.old_string:
// 预览全屏时藏掉左上角红黄绿系统按钮——它和右侧自家关闭图标太像，容易让人误点
ipcMain.handle('win:traffic', (e, { show }) => {
  if (!win || win.isDestroyed() || typeof win.setWindowButtonVisibility !== 'function') return;
  win.setWindowButtonVisibility(!!show);
});

input.new_string:
// 预览全屏时藏掉左上角红黄绿系统按钮——它和右侧自家关闭图标太像，容易让人误点
ipcMain.handle('win:traffic', (e, { show }) => {
  if (!win || win.isDestroyed() || typeof win.setWindowButtonVisibility !== 'function') return;
  win.setWindowButtonVisibility(!!show);
});

// 原生文件夹选择器：让用户直接选任意文件夹，不必在面包屑/快速入口里一级级点进去
ipcMain.handle('dialog:pick-dir', (e, { start } = {}) => {
  if (!win || win.isDestroyed()) return null;
  const opts = { properties: ['openDirectory', 'createDirectory'], title: M('选择文件夹', 'Choose a folder') };
  if (start && fs.existsSync(start)) opts.defaultPath = start;
  const picked = dialog.showOpenDialogSync(win, opts);
  return picked && picked[0] ? picked[0] : null;
});

contextBridge.exposeInMainWorld('fanboxDialog', {
  // 原生文件夹选择器，返回选中的绝对路径（取消则 null）
  pickDir: (start) => ipcRenderer.invoke('dialog:pick-dir', { start }),
});

contextBridge.exposeInMainWorld('fanboxWin', {

.nav-title svg { flex-shrink: 0; }
.pickdir-btn { margin-left: auto; display: inline-flex; align-items: center; gap: 4px; padding: 2px 7px; border: 1px solid var(--border, rgba(128,128,128,0.25)); border-radius: 6px; background: transparent; color: var(--text-dim); font-size: 11px; letter-spacing: 0; text-transform: none; cursor: pointer; }
.pickdir-btn:hover { background: var(--accent-soft); color: var(--accent); border-color: var(--accent); }
.pickdir-btn svg { width: 12px; height: 12px; }

// 直接选文件夹：调系统原生选择器，省去在面包屑/快速入口一级级点（仅桌面 app 有原生选择器）
const pickDirBtn = $('#btn-pickdir');
if (pickDirBtn) {
  if (window.fanboxDialog && window.fanboxDialog.pickDir) {
    pickDirBtn.onclick = async () => {
      const dir = await window.fanboxDialog.pickDir(state.cwd || state.home);
      if (dir) navigate(dir);
    };
  } else {
    pickDirBtn.style.display = 'none'; // 浏览器版无原生选择器
  }
}
$('#btn-recent').onclick = showRecent;

